package in.tucor.api.buyer; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.*; import java.util.UUID;
@Entity @Table(name="market_listings") public class MarketListing {@Id public UUID id;@Column(name="public_id") public String publicId;@Column(name="seller_id") public UUID sellerId;@Column(name="oil_type") public String oilType;@Column(name="volume_liters") public int volumeLiters;@Column(name="grade_label") public String gradeLabel;@Column(name="price_per_liter") public BigDecimal pricePerLiter;public String status;public String city;public String state;public String region;@Column(name="collection_frequency") public String collectionFrequency;@Column(name="available_from") public LocalDate availableFrom;@Column(name="seller_ref") public String sellerRef;@Column(name="quality_notes") public String qualityNotes;@Column(name="moisture_content") public String moistureContent;@Column(name="acid_value") public String acidValue;public String ffa;@Column(name="iodine_value") public String iodineValue;@Column(name="listing_date") public LocalDate listingDate;@Column(name="min_order_liters") public int minOrderLiters;@Column(name="created_at") public Instant createdAt;@PrePersist void create(){if(id==null)id=UUID.randomUUID();if(createdAt==null)createdAt=Instant.now();if(listingDate==null)listingDate=LocalDate.now();}}